export type RateLimiterMode = 'fixed' | 'sliding'

export interface RateLimiterOptions {
  max: number
  windowMs: number
  mode: RateLimiterMode
}

interface FixedBucket {
  windowStart: number
  count: number
}

export class RateLimiter {
  private readonly max: number
  private readonly windowMs: number
  private readonly mode: RateLimiterMode
  private readonly fixedBuckets = new Map<string, FixedBucket>()
  private readonly slidingTimestamps = new Map<string, number[]>()

  constructor(options: RateLimiterOptions) {
    this.max = options.max
    this.windowMs = options.windowMs
    this.mode = options.mode
  }

  allow(key: string): boolean {
    const now = Date.now()
    return this.mode === 'fixed' ? this.allowFixed(key, now) : this.allowSliding(key, now)
  }

  private allowFixed(key: string, now: number): boolean {
    const windowStart = Math.floor(now / this.windowMs) * this.windowMs
    const bucket = this.fixedBuckets.get(key)
    if (!bucket || bucket.windowStart !== windowStart) {
      this.fixedBuckets.set(key, { windowStart, count: 1 })
      return true
    }
    if (bucket.count >= this.max) return false
    bucket.count++
    return true
  }

  private allowSliding(key: string, now: number): boolean {
    const cutoff = now - this.windowMs
    const timestamps = this.slidingTimestamps.get(key) ?? []
    let i = 0
    while (i < timestamps.length && timestamps[i] <= cutoff) i++
    const active = i === 0 ? timestamps : timestamps.slice(i)
    if (active.length >= this.max) {
      if (active !== timestamps) this.slidingTimestamps.set(key, active)
      return false
    }
    active.push(now)
    this.slidingTimestamps.set(key, active)
    return true
  }
}

